#pragma once
#include "detection.h"
#include "packet_helpers.h"
namespace dragon::analysis {
enum class Filter:uint8_t {All,Beacons,Probes,Disconnect,Eapol,Pwnagotchi,Detections,Authentication,Count};
inline constexpr const char* filterNames[]={"All Wi-Fi frames","Beacons / responses","Probe requests","Deauth / disassociation","EAPOL / PMKID","Pwnagotchi peers","Detected device families","Authentication / SAE"};
inline bool accepts(Filter kind,const WifiFrame& f){if(!f.valid)return false;switch(kind){case Filter::All:return true;case Filter::Beacons:return f.beacon;case Filter::Probes:return f.probe;case Filter::Disconnect:return f.deauth||f.disassoc;case Filter::Eapol:return f.eapol;case Filter::Pwnagotchi:return f.match.family==Family::Pwnagotchi;case Filter::Detections:return f.match.confidence!=Confidence::None;case Filter::Authentication:return f.frameType==0xb0&&!f.protectedFrame;default:return false;}}
// EAPOL message observations are not proof of a complete/replay-consistent handshake.
inline unsigned eapolMessage(const uint8_t* p,size_t n){auto f=parseWifi(p,n);if(!f.eapol)return 0;size_t h=24;if((p[1]&3)==3)h+=6;if(p[0]&0x80)h+=2;if((p[0]&0x80)&&(p[1]&0x80))h+=4;size_t at=h+8;if(n-at<99||p[at+1]!=3)return 0;size_t length=size_t(p[at+2])<<8|p[at+3];if(length<95||length>n-at-4||(p[at+4]!=2&&p[at+4]!=254))return 0;uint16_t flags=uint16_t(p[at+5])<<8|p[at+6];if(!(flags&8)||flags&0x0c00)return 0;bool ack=flags&0x80,mic=flags&0x100,install=flags&0x40,secure=flags&0x200;return ack?(mic&&install?3:!mic&&!install?1:0):mic&&!install?(secure?4:2):0;}
inline bool hasPmkid(const uint8_t* p,size_t n){if(!eapolMessage(p,n))return false;size_t h=24;if((p[1]&3)==3)h+=6;if(p[0]&0x80)h+=2;if((p[0]&0x80)&&(p[1]&0x80))h+=4;size_t at=h+8;if(p[at+5]&0x10)return false;size_t length=size_t(p[at+97])<<8|p[at+98],total=size_t(p[at+2])<<8|p[at+3];if(length>total-95)return false;size_t end=at+99+length;for(at+=99;at<end;){if(end-at<2)return false;unsigned id=p[at++],len=p[at++];if(len>end-at)return false;if(id==221&&len==20&&p[at]==0&&p[at+1]==0x0f&&p[at+2]==0xac&&p[at+3]==4)return true;at+=len;}return false;}
struct Counters {uint32_t frames=0,beacons=0,probes=0,disconnect=0,eapol=0,peers=0,detections=0,protectedFrames=0,retries=0,keyMessages[5]{},pmkid=0,sae=0;void observe(const uint8_t* p,size_t n,const WifiFrame& f){if(!f.valid)return;++frames;beacons+=f.beacon;probes+=f.probe;disconnect+=f.deauth||f.disassoc;eapol+=f.eapol;peers+=f.match.family==Family::Pwnagotchi;detections+=f.match.confidence!=Confidence::None;protectedFrames+=f.protectedFrame;retries+=f.retry;if(f.eapol){++keyMessages[eapolMessage(p,n)];pmkid+=hasPmkid(p,n);}sae+=f.frameType==0xb0&&!f.protectedFrame&&n>=32&&p[24]==3&&p[25]==0&&p[26]==1&&p[27]==0;}};
struct Probe {bool used=false;uint8_t mac[6]{},ssid[32]{},length=0,channel=0;int8_t rssi=-127;uint32_t seen=0,count=0;};
inline void observeProbe(Probe* rows,unsigned capacity,const WifiFrame& f,int rssi,uint8_t channel,uint32_t now){if(!rows||!capacity||!f.valid||!f.probe||f.ssidLength>32)return;unsigned slot=0;uint32_t age=0;for(unsigned i=0;i<capacity;++i){auto& a=rows[i];if(!a.used||(!memcmp(a.mac,f.source,6)&&a.length==f.ssidLength&&!memcmp(a.ssid,f.ssid,f.ssidLength))){slot=i;break;}if(now-a.seen>=age){age=now-a.seen;slot=i;}}auto& a=rows[slot];if(!a.used||memcmp(a.mac,f.source,6)||a.length!=f.ssidLength||memcmp(a.ssid,f.ssid,f.ssidLength))a={};a.used=true;memcpy(a.mac,f.source,6);memcpy(a.ssid,f.ssid,f.ssidLength);a.length=f.ssidLength;a.channel=channel;a.rssi=rssi;a.seen=now;++a.count;}
inline uint8_t nextChannel(uint8_t current,uint16_t mask){mask&=0x7ff;if(!mask)return 1;for(unsigned i=0;i<11;++i){current=current%11+1;if(mask&(1u<<(current-1)))return current;}return 1;}
}
